function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) return fn.apply(this, args);
    return (...nextArgs) => curried.apply(this, [...args, ...nextArgs]);
  };
}

function pipe(...fns) {
  return (x) => fns.reduce((v, f) => f(v), x);
}

function compose(...fns) {
  return (x) => fns.reduceRight((v, f) => f(v), x);
}

curry-compose.referenceSolutionTs:
function curry(fn: (...args: any[]) => any): (...args: any[]) => any {
  return function curried(this: any, ...args: any[]): any {
    if (args.length >= fn.length) return fn.apply(this, args);
    return (...nextArgs: any[]) => curried.apply(this, [...args, ...nextArgs]);
  };
}

function pipe(...fns: Array<(arg: any) => any>): (x?: any) => any {
  return (x?: any) => fns.reduce((v, f) => f(v), x);
}

function compose(...fns: Array<(arg: any) => any>): (x?: any) => any {
  return (x?: any) => fns.reduceRight((v, f) => f(v), x);
}

rate-limiter-middleware.promptSeed:
### `rateLimiter(options: RateLimiterOptions): RateLimiterMiddleware`

```ts
interface RateLimiterOptions {
  limit: number;
  windowMs: number;
  now?: () => number;
}

interface RateLimiterMiddleware {
  (req: { ip: string; [key: string]: any }, res: any, next: () => void): void;
  size: () => number;
}
```

Write `rateLimiter({ limit, windowMs, now = Date.now })` returning an Express-style middleware `(req, res, next)`:

- **Token Bucket per Client**: Allows each client (`req.ip`) up to `limit` requests per `windowMs` using a token bucket.
- **Rate Limit Exceeded**: When a client has no available tokens:
  - Do **NOT** call `next()`.
  - Set `res.statusCode = 429`.
  - Set a `Retry-After` header using `res.setHeader` (rounded up to whole seconds until the next token refills).
  - Call `res.end()`.
- **Memory Eviction**: Evict client buckets that have remained idle for longer than `windowMs` to prevent memory leaks.
- **Client Count**: Expose `middleware.size()` returning the count of currently tracked clients.

