function addTag(tags, input, { max = Infinity } = {}) {
  const tag = input.trim();
  const exists = tags.some((t) => t.toLowerCase() === tag.toLowerCase());
  if (!tag || exists || tags.length >= max) return [...tags];
  return [...tags, tag];
}

function removeTag(tags, index) {
  return tags.filter((_, i) => i !== index);
}

function parseTags(text) {
  return text.split(/[,\r\n]+/).reduce((list, part) => addTag(list, part), []);
}

add-tag-rules.referenceSolutionTs:
function addTag(tags: string[], input: string, { max = Infinity }: { max?: number } = {}): string[] {
  const tag = input.trim();
  const exists = tags.some((t) => t.toLowerCase() === tag.toLowerCase());
  if (!tag || exists || tags.length >= max) return [...tags];
  return [...tags, tag];
}

function removeTag(tags: string[], index: number): string[] {
  return tags.filter((_, i) => i !== index);
}

function parseTags(text: string): string[] {
  return text.split(/[,\r\n]+/).reduce<string[]>((list, part) => addTag(list, part), []);
}

